export const LORE = [
  {id:'quiet_earth',title:'The Quiet Earth',text:'Ninety-three years ago, Earth’s atmosphere failed in patches. The evacuation was real, but incomplete. The final transmission ordered a temporary quarantine. No one ever received its cancellation.'},
  {id:'severance',title:'The Severance',text:'Orbital cooling mirrors fell out of alignment during a global power crisis. Some governments cut the elevators to stop the cascade. Others kept them running so people could escape. Every faction teaches a different order of events.'},
  {id:'sparrow',title:'A Sparrow Class Hauler',text:'Cinder is a Sparrow-class hauler: one pilot, a cramped cargo bay, and more hope than shielding. Salvagers call the class a kettle with a cockpit. Properly maintained, it can outlive the company that made it.'},
  {id:'lanes',title:'What Light Speed Costs',text:'A fold drive does not make space small. It borrows an old lane’s geometry, crosses in a flash, then needs fuel and a safe arrival. Early haulers rely on local engines until they can afford a field coil and trustworthy charts.'},
  {id:'kettle_history',title:'The Station That Stayed',text:'Kettle began as six evacuation transports tied together while their captains argued about where to go. The engineers connected the air systems. The families opened a school. By the time the argument ended, it was home.'},
  {id:'air_pact',title:'The Pact of Air',text:'Earth’s surviving regions pooled their climate machinery under an emergency pact. Maintaining it required decades without orbital traffic. The silence may have been a shield, not a grave.'},
  {id:'living_registry',title:'A Living Registry',text:'A census relay still receives population corrections from Earth. The numbers change slowly. Births. Deaths. Household moves. Whatever has survived there is neither empty nor waiting to be claimed.'},
  {id:'seedvault',title:'The Witness Seed Vault',text:'The vault stores hardy crops and a manual written for farmers, not admirals. Its oldest inventory entry reads: “For the day the weather belongs to everyone again.”'},
  {id:'meridian_patent',title:'The Anchor Patent',text:'Meridian financed the repair of the first post-Severance lanes. The patent covered its new safety systems. Over time, its lawyers extended the claim to the lanes themselves. The original engineers objected; their signatures remain in the archive.'},
  {id:'union_charter',title:'The Freewake Charter',text:'No captain may sell another crew member’s air, water, or passage. The charter was written after a rescue ship demanded lifetime labor contracts from the people it saved. Not every Union port has lived up to it.'},
  {id:'cinder_debt',title:'A Debt of Warmth',text:'Cinder families mark rescue debts with a strip of red cloth tied beside the airlock. A ship displaying one can ask for sanctuary. Even raiders sometimes honor it. Sometimes is an uncomfortable foundation for a civilization.'},
  {id:'open_frequency',title:'The Open Frequency',text:'The first evacuation signal was a public channel. When factions encrypted their networks, ordinary ships kept it alive with weather reports, lost names, recipes, and calls for help. A galaxy can share a frequency without sharing a government.'},
  {id:'silent_engine',title:'The Engine Beneath Palimpsest',text:'The buried machine measures how local space bends. It was old before humanity arrived, yet it responds to careful calibration. It offers no prophecy, only measurements that make the long way home possible.'},
  {id:'return_ethic',title:'Returning Is Not Ownership',text:'People who stayed on Earth rebuilt under conditions the outer colonies cannot imagine. Coming home may mean asking permission. The hardest part of the journey is admitting that ancestry is not a deed.'}
];

